// closure.c: closures and the cells they capture.

#include "adamic.h"

adamic_cell *adamic_cell_new(adamic_value value, bool references) {
	adamic_cell *cell = adamic_allocate(sizeof *cell, adamic_kind_cell);
	cell->references = references;
	cell->ready = true;
#ifdef ADAMIC_CANONICAL_CLOSURES
	cell->owner = NULL;
#endif
	cell->value = value;
	return cell;
}

adamic_closure *(adamic_closure_new)(adamic_code code, size_t count) {
	adamic_closure *closure = adamic_allocate(sizeof *closure + count * sizeof closure->cells[0], adamic_kind_closure);
	closure->code = code;
#ifdef ADAMIC_CLOSURE_CONVENTION
 closure->counted = false;
#endif
#ifdef ADAMIC_CLOSURE_RECEIVERS
 closure->receiver = false;
#endif
	closure->count = count;
#ifdef ADAMIC_CANONICAL_CLOSURES
	closure->canonical_owner = NULL;
	closure->canonical_previous = NULL;
	closure->canonical_next = NULL;
#endif
	for (size_t index = 0; index < count; index++) {
		closure->cells[index] = NULL;
	}
	return closure;
}

#ifdef ADAMIC_CANONICAL_CLOSURES
adamic_environment *adamic_environment_new(size_t count) {
	adamic_environment *environment = adamic_allocate(sizeof *environment + count * sizeof environment->cells[0], adamic_kind_environment);
	environment->count = count;
	environment->functions = NULL;
	for (size_t index = 0; index < count; index++) {
		environment->cells[index] = (adamic_cell){.heap = {.kind = adamic_kind_cell}, .owner = environment};
	}
	return environment;
}

// A live value is unique for its code and activation. If no owner kept it, a
// later reference can recreate it: no surviving reference can observe that gap.
// Captured cells keep the frame alive; its cache never keeps a closure alive.
adamic_closure *(adamic_closure_canonical)(adamic_cell *identity, adamic_code code, size_t count, adamic_cell *const cells[]) {
	adamic_environment *owner = identity->owner;
	for (adamic_closure *held = owner->functions; held != NULL; held = held->canonical_next) {
#ifdef ADAMIC_CLOSURE_CONVENTION
        if (held->counted) { continue; }
#endif
		if (held->code == code) {
			return adamic_retain(held);
		}
	}
	adamic_closure *closure = adamic_closure_new(code, count);
	for (size_t index = 0; index < count; index++) {
		closure->cells[index] = adamic_retain(cells[index]);
	}
	closure->canonical_owner = owner;
	closure->canonical_next = owner->functions;
	if (owner->functions != NULL) {
		owner->functions->canonical_previous = closure;
	}
	owner->functions = closure;
	return closure;
}


#ifdef ADAMIC_CLOSURE_CONVENTION
adamic_closure *(adamic_counted_closure_canonical)(adamic_cell *identity, adamic_counted_code code, size_t count, adamic_cell *const cells[]) {
 adamic_environment *owner = identity->owner;
 for (adamic_closure *held = owner->functions; held != NULL; held = held->canonical_next) {
 if (held->counted && held->counted_code == code) { return adamic_retain(held); }
 }
 adamic_closure *closure = adamic_counted_closure_new(code, count);
 for (size_t index = 0; index < count; index++) { closure->cells[index] = adamic_retain(cells[index]); }
 closure->canonical_owner = owner;
 closure->canonical_next = owner->functions;
 if (owner->functions != NULL) { owner->functions->canonical_previous = closure; }
 owner->functions = closure;
 return closure;
}
#endif

void adamic_closure_uncache(adamic_closure *closure) {
	adamic_environment *owner = closure->canonical_owner;
	if (owner == NULL) {
		return;
	}
	if (closure->canonical_previous != NULL) {
		closure->canonical_previous->canonical_next = closure->canonical_next;
	} else {
		owner->functions = closure->canonical_next;
	}
	if (closure->canonical_next != NULL) {
		closure->canonical_next->canonical_previous = closure->canonical_previous;
	}
}

#endif

internal/native/runtime/count.c:
// count.c: the counts a counted build keeps (count.h).

#include "count.h"

#include <stdio.h>
#include <unistd.h>

adamic_counts adamic_counted;

void adamic_count_allocation(void) {
	adamic_counted.allocations++;
	adamic_counted.live++;
	if (adamic_counted.live > adamic_counted.peak) {
		adamic_counted.peak = adamic_counted.live;
	}
}

void adamic_count_report(void) {
	char line[200];
	int length = snprintf(line, sizeof line, "adamic: counts: allocations %zu frees %zu retains %zu releases %zu peak %zu regions %zu\n",
		adamic_counted.allocations, adamic_counted.frees, adamic_counted.retains, adamic_counted.releases, adamic_counted.peak, adamic_counted.regions);
	if (length > 0 && (size_t)length < sizeof line) {
		// Best effort, as a panic's message is: stderr may be what failed.
		(void)!write(2, line, (size_t)length);
	}
}

#ifdef ADAMIC_COUNT
// A finished program reports once main has returned, after it let go of its globals. A panic reports
// from adamic_panic, since it leaves by _exit and runs no destructor.
__attribute__((destructor)) static void report_at_exit(void) {
	adamic_count_report();
}
#endif

internal/native/runtime/count.h:
// count.h: what a counted build counts (native.Options.Count, which defines ADAMIC_COUNT). Counts are
// deterministic, unlike time, so they can be measured anywhere: the oracle's counts table holds every
// fixture's, and borrow inference and reuse in place are measured against it (docs/memory.md).
//
// An allocation is a heap value made (adamic_allocate) and a free is one freed; the buffers behind an
// array's elements or a map's table aren't heap values and aren't counted. A retain or a release is
// a call to adamic_retain or adamic_release, whatever it's given: each one is work the compiler asked
// for, even on an immortal constant or undefined. Outside a counted build every hook is nothing.

#ifndef ADAMIC_COUNT_H
#define ADAMIC_COUNT_H

#include <stddef.h>

typedef struct adamic_counts {
	size_t allocations;
	size_t frees;
	size_t retains;
	size_t releases;
	// live is allocations less frees, and peak the most that were ever live at once.
	size_t live;
	size_t peak;
	// regions is the values let go of with their region rather than freed one at a time (region.c):
	// a finished program's allocations are its frees and its regions.
	size_t regions;
} adamic_counts;

extern adamic_counts adamic_counted;

void adamic_count_allocation(void);

// adamic_count_report writes the counts to stderr, as one line the oracle reads:
// adamic: counts: allocations 3 frees 3 retains 7 releases 10 peak 2 regions 0
void adamic_count_report(void);

#ifdef ADAMIC_COUNT
#define ADAMIC_COUNT_ALLOCATION() adamic_count_allocation()
#define ADAMIC_COUNT_FREE() (adamic_counted.frees++, adamic_counted.live--)
#define ADAMIC_COUNT_RETAIN() (adamic_counted.retains++)
#define ADAMIC_COUNT_RELEASE() (adamic_counted.releases++)
#define ADAMIC_COUNT_REPORT() adamic_count_report()
#define ADAMIC_COUNT_REGION(count) (adamic_counted.regions += (count), adamic_counted.live -= (count))
#else
#define ADAMIC_COUNT_ALLOCATION() ((void)0)
#define ADAMIC_COUNT_FREE() ((void)0)
#define ADAMIC_COUNT_RETAIN() ((void)0)
#define ADAMIC_COUNT_RELEASE() ((void)0)
#define ADAMIC_COUNT_REPORT() ((void)0)
#define ADAMIC_COUNT_REGION(count) ((void)(count))
#endif

#endif

internal/native/runtime/directory.c:
// directory.c: the file system a walk needs, opened in 0.2: readDirectory and fileStatus.
//
// Each answers as Node does on the same machine. readdirSync's names come from libuv's scandir,
// sorted by strcmp on the raw bytes, without . and .., and are decoded as UTF-8 after the sort, so
// the order is the bytes' even where a name isn't valid UTF-8. statSync follows a symbolic link and
// lstatSync doesn't; fileStatus gives the type and size of what a path names, following a link, and
// says whether the path itself is one.

// lstat, S_ISLNK and the directory calls are POSIX's, which strict C11 doesn't show without asking.
#define _POSIX_C_SOURCE 200809L

#include "adamic.h"

#include <dirent.h>
#include <errno.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

static const char *const ok_listing_names[] = {"kind", "names"};
static const char *const ok_status_names[] = {"kind", "type", "size", "symbolicLink"};
static const char *const error_names[] = {"kind", "message"};
static const bool two_references[] = {true, true};
static const bool status_references[] = {true, true, false, false};
static const adamic_shape listing_shape = {2, ok_listing_names, two_references, NULL};
static const adamic_shape status_shape = {4, ok_status_names, status_references, NULL};
static const adamic_shape error_shape = {2, error_names, two_references, NULL};
static adamic_string ok_kind = ADAMIC_STRING("Ok");
static adamic_string error_kind = ADAMIC_STRING("Error");
static adamic_string file_type = ADAMIC_STRING("file");
static adamic_string directory_type = ADAMIC_STRING("directory");
static adamic_string other_type = ADAMIC_STRING("other");

// failure is { kind: 'Error', message }: "<prefix><path>: <reason>", in Adamic's own words, the same
// on every platform. The JavaScript runtime says the same (oracle/adamic.mjs), from Node's error
// codes, which are these errno names.
static adamic_object *failure(const char *prefix, size_t prefix_length, const adamic_string *path, int error, bool listing) {
	adamic_string before = {{0, adamic_kind_string, 0}, prefix_length, prefix, 0, NULL, NULL, 0};
	static adamic_string missing_file = ADAMIC_STRING(": no such file");
	static adamic_string missing_directory = ADAMIC_STRING(": no such directory");
	static adamic_string not_directory = ADAMIC_STRING(": not a directory");
	static adamic_string denied = ADAMIC_STRING(": permission denied");
	static adamic_string failed = ADAMIC_STRING(": failed");
	adamic_string *reason = &failed;
	switch (error) {
	case ENOENT:
		reason = listing ? &missing_directory : &missing_file;
		break;
	case ENOTDIR:
		reason = listing ? &not_directory : &missing_file;
		break;
	case EACCES:
	case EPERM:
		reason = &denied;
		break;
	}
	adamic_object *result = adamic_object_new(&error_shape);
	result->slots[0].reference = &error_kind;
	result->slots[1].reference = adamic_string_concat(3, (adamic_string *const[]){&before, (adamic_string *)path, reason});
	return result;
}

static int compare_names(const void *left, const void *right) {
	return strcmp(*(char *const *)left, *(char *const *)right);
}

adamic_object *adamic_read_directory(const adamic_string *path) {
	static const char prefix[] = "cannot read directory ";
	// What was printed comes first, as on Node, before anything of the file system is looked at.
	adamic_output_flush();
#ifdef ADAMIC_TARGET_WASI
	// WASI libc treats the empty path as cwd; Node reports ENOENT.
	if (path->length == 0) {
		return failure(prefix, sizeof prefix - 1, path, ENOENT, true);
	}
#endif
	char *name = adamic_path_bytes(path);
	if (name == NULL) {
		return failure(prefix, sizeof prefix - 1, path, 0, true);
	}
	DIR *directory = opendir(name);
	free(name);
	if (directory == NULL) {
		return failure(prefix, sizeof prefix - 1, path, errno, true);
	}
	char **names = NULL;
	size_t count = 0, capacity = 0;
	int error = 0;
	for (;;) {
		errno = 0;
		struct dirent *entry = readdir(directory);
		if (entry == NULL) {
			error = errno;
			break;
		}
		if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
			continue;
		}
		if (count == capacity) {
			capacity = capacity == 0 ? 16 : capacity * 2;
			char **grown = realloc(names, capacity * sizeof *grown);
			if (grown == NULL) {
				static const char message[] = "out of memory";
				adamic_panic(message, sizeof message - 1);
			}
			names = grown;
		}
		names[count] = strdup(entry->d_name);
		if (names[count] == NULL) {
			static const char message[] = "out of memory";
			adamic_panic(message, sizeof message - 1);
		}
		count++;
	}
	closedir(directory);
	if (error != 0) {
		for (size_t index = 0; index < count; index++) {
			free(names[index]);
		}
		free(names);
		return failure(prefix, sizeof prefix - 1, path, error, true);
	}
	if (count > 1) {
		qsort(names, count, sizeof *names, compare_names);
	}
	adamic_array *listed = adamic_array_new(count, true);
	for (size_t index = 0; index < count; index++) {
		adamic_array_push(listed, (adamic_value){.reference = adamic_decode_utf8((const unsigned char *)names[index], strlen(names[index]))});
		free(names[index]);
	}
	free(names);
	adamic_object *result = adamic_object_new(&listing_shape);
	result->slots[0].reference = &ok_kind;
	result->slots[1].reference = listed;
	return result;
}

adamic_object *adamic_file_status(const adamic_string *path) {
	static const char prefix[] = "cannot read status of ";
	// What was printed comes first, as on Node: the path may be stdout itself, its size what's
	// been written.
	adamic_output_flush();
#ifdef ADAMIC_TARGET_WASI
	// WASI libc treats the empty path as cwd; Node reports ENOENT.
	if (path->length == 0) {
		return failure(prefix, sizeof prefix - 1, path, ENOENT, false);
	}
#endif
	char *name = adamic_path_bytes(path);
	if (name == NULL) {
		return failure(prefix, sizeof prefix - 1, path, 0, false);
	}
	struct stat link, status;
	int failed = lstat(name, &link);
	bool symbolic = failed == 0 && S_ISLNK(link.st_mode);
	if (failed == 0) {
		failed = symbolic ? stat(name, &status) : 0;
		if (!symbolic) {
			status = link;
		}
	}
	int error = errno;
	free(name);
	if (failed != 0) {
		return failure(prefix, sizeof prefix - 1, path, error, false);
	}
	adamic_object *result = adamic_object_new(&status_shape);
	result->slots[0].reference = &ok_kind;
	result->slots[1].reference = S_ISREG(status.st_mode) ? &file_type : S_ISDIR(status.st_mode) ? &directory_type : &other_type;
	result->slots[2].number = (double)status.st_size;
	result->slots[3].boolean = symbolic;
	return result;
}

