 const char suffix[] = "' of object '#<Object>'";
 size_t length = sizeof prefix - 1 + strlen(name) + sizeof suffix - 1;
 char *message = malloc(length + 1);
 if (message == NULL) adamic_panic("out of memory", sizeof "out of memory" - 1);
