		adamic_panic(message, sizeof message - 1);
	}
	for (size_t k = 0; k < object->shape->count; k++)
		if (strcmp(object->shape->names[k], "done") == 0)
			return (adamic_maybe_boolean){true, object->slots[k].boolean};
