// Private string search implementation, included only by string.c.

// Searching by WTF-8 bytes finds exactly what searching by UTF-16 units does, with one exception: a
// search that begins with a lone low surrogate or ends with a lone high one can match half of a
// supplementary character, which UTF-16 sees and the bytes (four of them, whole) don't. Only those
// searches go unit by unit.
static bool halves_pairs(const adamic_string *search) {
	if (search->units == search->length + 1) {
		return false;
	}
	units walk = units_start(search);
	unsigned unit, first = 0, last = 0;
	bool any = false;
	while (units_next(&walk, &unit)) {
		if (!any) {
			first = unit;
		}
		last = unit;
		any = true;
	}
	return any && ((first >= 0xdc00 && first <= 0xdfff) || (last >= 0xd800 && last <= 0xdbff));
}

// to_units is a string's UTF-16 code units, in a buffer the caller frees.
static unsigned *to_units(const adamic_string *string, size_t *count) {
	// A string's units are never more than its bytes.
	unsigned *buffer = malloc((string->length + 1) * sizeof *buffer);
	if (buffer == NULL) {
		static const char message[] = "out of memory";
		adamic_panic(message, sizeof message - 1);
	}
	units walk = units_start(string);
	*count = 0;
	while (units_next(&walk, &buffer[*count])) {
		(*count)++;
	}
	return buffer;
}

// unit_index_of is the first UTF-16 index at or after from where search's units are, or -1.
static double unit_index_of(const unsigned *haystack, size_t haystack_count, const unsigned *needle, size_t needle_count, size_t from) {
	for (size_t at = from; at + needle_count <= haystack_count; at++) {
		if (memcmp(haystack + at, needle, needle_count * sizeof *needle) == 0) {
			return (double)at;
		}
	}
	return -1;
}

double adamic_string_index_of(const adamic_string *string, const adamic_string *search) {
	return adamic_string_index_of_at(string, search, 0);
}

double adamic_string_index_of_at(const adamic_string *string, const adamic_string *search, size_t from) {
	if (search->length == 0) {
		return (double)from;
	}
	if (string->units == string->length + 1) {
		// ASCII positions are bytes. Even an uncounted needle can be compared by bytes:
		// no surrogate half can match this haystack.
		if (from > string->length || search->length > string->length - from) {
			return -1;
		}
		for (size_t offset = from; offset <= string->length - search->length; offset++) {
			if (string->bytes[offset] == search->bytes[0] &&
				memcmp(string->bytes + offset, search->bytes, search->length) == 0) {
				return (double)offset;
			}
		}
		return -1;
	}
	if (halves_pairs(search)) {
		size_t haystack_count, needle_count;
		unsigned *haystack = to_units(string, &haystack_count), *needle = to_units(search, &needle_count);
		double found = unit_index_of(haystack, haystack_count, needle, needle_count, from);
		free(haystack);
		free(needle);
		return found;
	}
	size_t start = 0;
	if (from > 0) {
		if (from >= adamic_string_units(string)) {
			return -1;
		}
		// From the low half of a pair, the search can begin only at the next code point: it doesn't
		// begin with a low half, or halves_pairs would have said so.
		bool low;
		start = adamic_string_locate(string, from, &low);
		if (low) {
			start += 4;
		}
	}
	for (size_t offset = start; offset + search->length <= string->length;) {
		if (memcmp(string->bytes + offset, search->bytes, search->length) == 0) {
			return (double)adamic_string_units_before(string, offset);
		}
		offset += sequence((unsigned char)string->bytes[offset]);
	}
	return -1;
}

// affix reports whether search's units are string's first (at_start) or last ones, unit by unit.
static bool affix(const adamic_string *string, const adamic_string *search, bool at_start) {
	size_t haystack_count, needle_count;
	unsigned *haystack = to_units(string, &haystack_count), *needle = to_units(search, &needle_count);
	bool found = needle_count <= haystack_count &&
		memcmp(haystack + (at_start ? 0 : haystack_count - needle_count), needle, needle_count * sizeof *needle) == 0;
	free(haystack);
	free(needle);
	return found;
}

double adamic_string_last_index_of(const adamic_string *string, const adamic_string *search) {
	if (search->length == 0) {
		return (double)adamic_string_units(string);
	}
	if (!halves_pairs(search)) {
		// A whole-character needle matches by bytes, as indexOf does. Look backward without
		// decoding the whole haystack into a temporary UTF-16 buffer for each search.
		if (search->length > string->length) {
			return -1;
		}
		for (size_t offset = string->length - search->length + 1; offset-- > 0;) {
			if (string->bytes[offset] == search->bytes[0] &&
				memcmp(string->bytes + offset, search->bytes, search->length) == 0) {
				return (double)adamic_string_units_before(string, offset);
			}
		}
		return -1;
	}
	size_t haystack_count, needle_count;
	unsigned *haystack = to_units(string, &haystack_count), *needle = to_units(search, &needle_count);
	double found = -1;
	if (needle_count <= haystack_count) {
		for (size_t at = haystack_count - needle_count + 1; at-- > 0;) {
			if (memcmp(haystack + at, needle, needle_count * sizeof *needle) == 0) {
				found = (double)at;
				break;
			}
		}
	}
	free(haystack);
	free(needle);
	return found;
}

internal/native/runtime/string_share.c:
// string_share.c: a slice of a string that reads its parent's bytes instead of copying them.
//
// A string is immutable, so a slice can point into the bytes of the string it was cut from, as a Go
// string does, and hold a reference to that string so the bytes outlive it. The slice is a string like
// any other: its own length, and its own caches (units and index, string_index.c), which start empty
// and are counted from its own bytes, so a checkpoint or a cursor is an offset into the slice, never
// into its parent. A slice of a slice points at the first one's owner, so no chain grows.
//
// Nothing ever writes into a string's bytes once it's made. If strings are ever reused in place (an
// append to a string only one holder has), a shared slice's bytes aren't its own to write, nor are
// the bytes of a string some slice reads (its count is more than one, so it isn't reused), and reuse
// would have to reset the cached units and index, which describe the old bytes.
//
// Sharing retains the ultimate owner, including its spare append capacity. Copy only when that
// storage exceeds SHARE_FRACTION times the view's own header and bytes. Including the header
// lets short views share small parents, without a minimum substring size. Constants pin nothing.

#include "adamic.h"

#include <string.h>

#ifndef SHARE_FRACTION
#define SHARE_FRACTION 8
#endif

adamic_string *adamic_string_share(const adamic_string *string, size_t offset, size_t size) {
	if (size == 0) {
		return adamic_retain(&adamic_string_empty);
	}
	const adamic_string *owner = string->owner != NULL ? string->owner : string;
	// A zero-count stack piece is borrowed, unlike a marked literal. It has no count a view
	// can keep, so even a whole slice must copy. Built literal indexes remain non-NULL.
	bool borrowed = owner->heap.references == 0 && owner->index == NULL;
	if (!borrowed && offset == 0 && size == string->length) {
		return adamic_retain((adamic_string *)string);
	}
	size_t storage = owner->capacity > owner->length ? owner->capacity : owner->length;
	// Avoid multiplication and addition overflow. ceil((header + storage) / fraction)
	// is at most header + view bytes exactly when the retained-storage bound holds.
	size_t minimum = storage / SHARE_FRACTION + sizeof *owner / SHARE_FRACTION;
	size_t remainder = storage % SHARE_FRACTION + sizeof *owner % SHARE_FRACTION;
	minimum += remainder / SHARE_FRACTION + (remainder % SHARE_FRACTION != 0);
	bool oversized = minimum > sizeof *owner && size < minimum - sizeof *owner;
	if (borrowed || (owner->heap.references != 0 && oversized)) {
		adamic_string *copy = adamic_string_allocate(size);
		if (size > 0) {
			memcpy((char *)copy->bytes, string->bytes + offset, size);
		}
		if (string->units == string->length + 1) {
			copy->units = size + 1;
		}
		return copy;
	}
	adamic_string *shared = adamic_allocate(sizeof *shared, adamic_kind_string);
	shared->length = size;
	shared->bytes = string->bytes + offset;
	shared->units = string->units == string->length + 1 ? size + 1 : 0;
	shared->index = NULL;
	shared->capacity = 0;
	// A constant's bytes last as long as the program, and need no one held for them.
	shared->owner = owner->heap.references == 0 ? NULL : adamic_retain((adamic_string *)owner);
	return shared;
}

internal/native/runtime/string_slice_imp:
// Private string slice implementation, included only by string.c.

// clamp_index is ECMAScript's relative index: ToIntegerOrInfinity, negative counts from the end, then
// clamped to [0, length].
static double clamp_index(double index, double length) {
	index = isnan(index) ? 0 : trunc(index);
	if (index < 0) {
		index = length + index < 0 ? 0 : length + index;
	}
	return index > length ? length : index;
}

adamic_string *adamic_string_slice(const adamic_string *string, double start, double end, bool has_end) {
	double length = adamic_string_length(string);
	double from = clamp_index(start, length);
	double to = has_end ? clamp_index(end, length) : length;
	if (!(from < to)) {
		return adamic_retain(&adamic_string_empty);
	}
	// Whole code points are their bytes, in one piece, shared with the string where that's worth it
	// (string_share.c). A slice that starts on the low half of a pair begins with that half, and one
	// that ends between the halves ends with the high one, each a lone surrogate, which isn't in the
	// string's bytes, so that slice is built.
	size_t first = (size_t)from, last = (size_t)to;
	if (string->units == string->length + 1) {
		return adamic_string_share(string, first, last - first);
	}
	bool low;
	size_t offset = adamic_string_locate(string, first, &low);
	if (low) {
		offset += 4;
	}
	bool ends_low = false;
	size_t stop = last < (size_t)length ? adamic_string_locate(string, last, &ends_low) : string->length;
	size_t middle = stop > offset ? stop - offset : 0;
	if (!low && !ends_low) {
		adamic_string *slice = adamic_string_share(string, offset, middle);
		slice->units = last - first + 1;
		return slice;
	}
	builder build = {NULL, 0, 0};
	if (low) {
		builder_unit(&build, unit_at(string, offset - 4, true));
	}
	if (middle > 0) {
		builder_add(&build, string->bytes + offset, middle);
	}
	if (ends_low) {
		builder_unit(&build, unit_at(string, stop, false));
	}
	adamic_string *slice = builder_finish(&build);
	slice->units = last - first + 1;
	return slice;
}

// One ASCII unit has only 128 possible values. Its immutable bytes and header can live
// with the runtime, so indexing does not mint a header or pin a source for one byte.
// Like the other string caches, initialization follows the single-threaded counting model.
static adamic_string *ascii_character(unsigned char value) {
	static char bytes[128];
	static adamic_string characters[128];
	adamic_string *character = &characters[value];
	if (character->units == 0) {
		bytes[value] = (char)value;
		*character = (adamic_string){{0, adamic_kind_string, 0}, 1, &bytes[value], 2, ADAMIC_LITERAL_INDEX, NULL, 0};
	}
	return character;
}

adamic_string *adamic_string_at(const adamic_string *string, double index) {
	// As for an array: an index is an integer from 0 up to the length in UTF-16 units, and anything
	// else (negative, a fraction, NaN, past the end) is a property the string doesn't have. Half of a
	// supplementary character is a lone surrogate, as slice makes it.
	if (!(index >= 0) || index != trunc(index) || index >= adamic_string_length(string)) {
		return NULL;
	}
	if (string->units == string->length + 1) {
		return ascii_character((unsigned char)string->bytes[(size_t)index]);
	}
	// An ASCII unit of a non-ASCII source is the same immutable character. Long sources
	// already carry a direct UTF-16 view; short ones keep the existing bounded walk.
	double unit = adamic_string_char_code_at(string, index);
	if (unit < 128) {
		return ascii_character((unsigned char)unit);
	}
	return adamic_string_slice(string, index, index + 1, true);
}

adamic_maybe_number adamic_string_code_point_at(const adamic_string *string, double position) {
	position = isnan(position) ? 0 : trunc(position);
	adamic_maybe_number missing = {false, 0};
	size_t length = string->units != 0 ? string->units - 1 : adamic_string_units(string);
	if (position < 0 || position >= (double)length) {
		return missing;
	}
	if (string->units == string->length + 1) {
		adamic_maybe_number found = {true, (double)(unsigned char)string->bytes[(size_t)position]};
		return found;
	}
	const uint16_t *view = adamic_string_unit_view(string);
	if (view != NULL) {
		size_t at = (size_t)position;
		unsigned point = view[at];
		if (point >= 0xd800 && point <= 0xdbff && at + 1 < length && view[at + 1] >= 0xdc00 && view[at + 1] <= 0xdfff) {
			point = 0x10000 + ((point - 0xd800) << 10) + (view[at + 1] - 0xdc00);
		}
		adamic_maybe_number found = {true, (double)point};
		return found;
	}
	// At the high half of a pair, the whole code point; anywhere else, the unit.
	bool low;
	size_t offset = adamic_string_locate(string, (size_t)position, &low);
	size_t size = sequence((unsigned char)string->bytes[offset]);
	unsigned point = decode((const unsigned char *)string->bytes + offset, size);
	if (low) {
		point = 0xdc00 + ((point - 0x10000) & 0x3ff);
	}
	adamic_maybe_number found = {true, (double)point};
	return found;
}

int adamic_string_compare(const adamic_string *left, const adamic_string *right) {
	// UTF-16 code unit order, as JavaScript's < compares: not UTF-8's byte order, which puts U+FFFF
	// before an emoji where UTF-16 puts it after.
	units left_walk = units_start(left), right_walk = units_start(right);
	for (;;) {
		unsigned left_unit, right_unit;
		bool left_more = units_next(&left_walk, &left_unit);
		bool right_more = units_next(&right_walk, &right_unit);
		if (!left_more || !right_more) {
			return left_more ? 1 : right_more ? -1 : 0;
		}
		if (left_unit != right_unit) {
			return left_unit < right_unit ? -1 : 1;
		}
	}
}

